export const code = async (inputs) => {
  const FALLBACK = [
    'overnight earnings results stock market reaction',
    'biggest stock market movers pre-market news'
  ];

  const clean = (value) => String(value === null || value === undefined ? '' : value)
    .replace(/[\r\n\t]+/g, ' ')
    .replace(/\s{2,}/g, ' ')
    .replace(/"/g, '')
    .trim();

  const clip = (value, limit) => {
    const t = clean(value);
    return t.length > limit ? t.slice(0, limit) : t;
  };

  // Etsi poimijan tekstisisalto milla tahansa vastausrakenteella.
  const deepText = (value, depth) => {
    const d = depth || 0;
    if (d > 6 || value === null || value === undefined) { return ''; }
    if (typeof value === 'string') { return value; }
    if (typeof value !== 'object') { return ''; }
    if (Array.isArray(value)) {
      for (const item of value) {
        const t = deepText(item, d + 1);
        if (t) { return t; }
      }
      return '';
    }
    if (Array.isArray(value.choices) && value.choices.length) {
      const c = value.choices[0] || {};
      const t = deepText(c.message !== undefined ? c.message : c.text, d + 1);
      if (t) { return t; }
    }
    for (const key of ['content', 'body', 'response', 'text', 'output', 'result', 'message', 'data']) {
      if (value[key] !== undefined && value[key] !== null) {
        const t = deepText(value[key], d + 1);
        if (t) { return t; }
      }
    }
    return '';
  };

  const collect = (value) => {
    let v = value;
    if (typeof v === 'string') {
      const t = v.trim();
      if (!t) { return []; }
      try { v = JSON.parse(t); } catch (e) { return []; }
    }
    if (Array.isArray(v)) { return v; }
    if (v && typeof v === 'object') {
      if (Array.isArray(v.events)) { return v.events; }
      return [v];
    }
    return [];
  };

  const rawText = deepText(inputs.raw !== undefined && inputs.raw !== null && inputs.raw !== '' ? inputs.raw : inputs.events_json, 0);
  const rawPreview = clip(rawText, 300);

  let jsonText = rawText.trim();
  const start = jsonText.indexOf('[');
  const end = jsonText.lastIndexOf(']');
  if (start !== -1 && end > start) {
    jsonText = jsonText.slice(start, end + 1);
  } else {
    const oStart = jsonText.indexOf('{');
    const oEnd = jsonText.lastIndexOf('}');
    if (oStart !== -1 && oEnd > oStart) { jsonText = jsonText.slice(oStart, oEnd + 1); }
  }

  const events = collect(jsonText);
  const queries = [];
  const quoteItems = [];

  const symbolClean = (value) => clean(value)
    .split(/[,;\s]+/).filter(Boolean)[0] || '';

  for (const item of events) {
    if (!item || typeof item !== 'object') { continue; }
    const name = clip(item.name || item.event || item.title || '', 90);
    const query = clip(item.query || item.search_query || '', 160) || clip(name + ' results outcome market reaction', 160);
    if (query && !queries.some((q) => q.toLowerCase() === query.toLowerCase()) && queries.length < 3) {
      queries.push(query);
    }
    const symbol = symbolClean(item.symbols || item.symbol || item.ticker || '');
    if (symbol && /^[A-Za-z0-9.\-=^]{1,15}$/.test(symbol)) {
      if (!quoteItems.some((q) => q.symbol === symbol)) {
        quoteItems.push({ symbol: symbol, label: name || symbol });
      }
    }
  }

  let fi = 0;
  while (queries.length < 3) {
    const fb = FALLBACK[fi % FALLBACK.length];
    fi += 1;
    if (!queries.some((q) => q.toLowerCase() === fb.toLowerCase())) { queries.push(fb); }
    if (fi > 4) { break; }
  }

  return {
    q1: queries[0] || FALLBACK[0],
    q2: queries[1] || FALLBACK[1],
    q3: queries[2] || 'weekly market outlook upcoming events',
    tickers: JSON.stringify(quoteItems.slice(0, 6)),
    parsed_count: events.length,
    raw_preview: rawPreview,
    watchlist: events.length
      ? events.slice(0, 3).map((item, i) => {
        const name = clip(item.name || item.event || item.title || '', 90) || ('tapahtuma ' + (i + 1));
        const timing = clip(item.timing || item.expected_timing || item.when || '', 80);
        const why = clip(item.why || item.reason || '', 220);
        return '- ' + name + (timing ? ' (ajankohta: ' + timing + ')' : '') + (why ? ' : ' + why : '');
      }).join(' ;; ')
      : 'ei tunnistettuja odotettuja tapahtumia'
  };
};

// step_17: viikon markkinaluvut Yahoo Financesta.
// Laskee viikon muutoksen = viimeisin päätös vs. noin viisi kaupankäyntipäivää aiemmin
// (range=1mo, interval=1d). Tuottaa sekä tekstin LLM:lle että valmiin HTML-taulukon,
// jossa on linkit ja värit (nousu vihreä, lasku punainen).
export const code = async (inputs) => {
  const symbols = [
    { id: 'OMX Helsinki 25', ticker: '^OMXH25' },
    { id: 'OMX Stockholm 30', ticker: '^OMX' },
    { id: 'STOXX Europe 600', ticker: '^STOXX' },
    { id: 'DAX (Saksa)', ticker: '^GDAXI' },
    { id: 'FTSE 100 (UK)', ticker: '^FTSE' },
    { id: 'CAC 40 (Ranska)', ticker: '^FCHI' },
    { id: 'S&P 500 (USA)', ticker: '^GSPC' },
    { id: 'Nasdaq Composite', ticker: '^IXIC' },
    { id: 'Dow Jones', ticker: '^DJI' },
    { id: 'Nikkei 225', ticker: '^N225' },
    { id: 'Hang Seng', ticker: '^HSI' },
    { id: 'KOSPI', ticker: '^KS11' },
    { id: 'US 10Y Treasury Yield', ticker: '^TNX' },
    { id: 'Brent Crude Oil', ticker: 'BZ=F' },
    { id: 'Gold Futures', ticker: 'GC=F' },
    { id: 'Copper Futures', ticker: 'HG=F' },
    { id: 'EUR/USD', ticker: 'EURUSD=X' },
    { id: 'USD/JPY', ticker: 'USDJPY=X' },
    { id: 'Bitcoin USD', ticker: 'BTC-USD' }
  ];

  const host = ['query2', 'finance', 'yahoo', 'com'].join('.');
  const baseUrl = 'https://' + host + '/v8/finance/chart/';
  const webHost = ['finance', 'yahoo', 'com'].join('.');
  const MINUS = '\u2212';
  const NBSP = '\u00a0';

  const fiNum = (n, dec) => {
    const s = Number(n).toFixed(dec);
    const parts = s.split('.');
    const grouped = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, NBSP);
    return parts[1] ? grouped + ',' + parts[1] : grouped;
  };

  const lines = [];
  const rows = [];

  for (const item of symbols) {
    const quoteUrl = 'https://' + webHost + '/quote/' + encodeURIComponent(item.ticker) + '/';
    let price = null;
    let changePct = null;
    let asOf = '';
    try {
      const url = baseUrl + encodeURIComponent(item.ticker) + '?interval=1d&range=1mo';
      const res = await fetch(url, {
        headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36' }
      });
      const data = await res.json();
      const r = (data && data.chart && data.chart.result && data.chart.result[0]) || null;
      const meta = (r && r.meta) || {};
      const q = (((r || {}).indicators || {}).quote || [])[0] || {};
      const series = (q.close || []).filter((v) => typeof v === 'number' && isFinite(v));
      if (series.length) {
        price = series[series.length - 1];
      } else if (typeof meta.regularMarketPrice === 'number') {
        price = meta.regularMarketPrice;
      }
      const base = series.length > 5 ? series[series.length - 6] : (series.length ? series[0] : null);
      if (typeof base === 'number' && base !== 0 && typeof price === 'number') {
        changePct = ((price - base) / base) * 100;
      }
      if (meta.regularMarketTime) {
        asOf = new Date(meta.regularMarketTime * 1000).toISOString().slice(0, 10);
      }
    } catch (e) { }

    if (typeof price !== 'number' || typeof changePct !== 'number') {
      lines.push(item.id + ': ei saatavilla | Link: ' + quoteUrl);
      continue;
    }

    const sign = changePct > 0 ? '+' : (changePct < 0 ? MINUS : '');
    const pctText = sign + fiNum(Math.abs(changePct), 2) + NBSP + '%';
    const color = changePct > 0 ? '#1a7f37' : (changePct < 0 ? '#c62828' : '#5b6675');
    lines.push(item.id + ': ' + fiNum(price, 2) + ' (' + pctText + ' viikon muutos' + (asOf ? ', ' + asOf : '') + ') | Link: ' + quoteUrl);
    rows.push('<tr><td><a href="' + quoteUrl + '" target="_blank" rel="noopener noreferrer">' + item.id + '</a></td>'
      + '<td style="text-align:right;white-space:nowrap;">' + fiNum(price, 2) + '</td>'
      + '<td style="text-align:right;white-space:nowrap;color:' + color + ';font-weight:600;">' + pctText + '</td></tr>');
  }

  const table = '<table style="width:100%;border-collapse:collapse;">'
    + '<caption style="caption-side:top;text-align:left;font-size:0.85rem;color:#5b6675;padding-bottom:8px;">Viikon muutos perjantain päätöksen mukaan (ei reaaliaikainen).</caption>'
    + '<thead><tr>'
    + '<th style="text-align:left;padding:8px;border-bottom:1px solid #e2e6ec;font-size:0.85rem;">Kohde</th>'
    + '<th style="text-align:right;padding:8px;border-bottom:1px solid #e2e6ec;font-size:0.85rem;">Taso</th>'
    + '<th style="text-align:right;padding:8px;border-bottom:1px solid #e2e6ec;font-size:0.85rem;">Viikon muutos</th>'
    + '</tr></thead><tbody>' + rows.join('') + '</tbody></table>';

  return {
    weeklyData: lines.join('\n'),
    weeklyTable: table
  };
};

export const code = async (inputs) => {
  const SEP = '  ;;  ';

  const cut = (text, limit) => {
    const t = String(text === null || text === undefined ? '' : text)
      .replace(/[\r\n\t]+/g, ' ')
      .replace(/[ ]{2,}/g, ' ')
      .trim();
    if (t.length <= limit) { return t; }
    const slice = t.slice(0, limit);
    const space = slice.lastIndexOf(' ');
    return (space > limit * 0.6 ? slice.slice(0, space) : slice) + ' ...';
  };

  const domain = (url) => {
    const m = String(url || '').match(/^https?:\/\/([^\/]+)/i);
    return m ? m[1].replace(/^www\./i, '') : '';
  };

  const parse = (value) => {
    let v = value;
    if (typeof v === 'string') {
      const t = v.trim();
      if (!t) { return {}; }
      try { v = JSON.parse(t); } catch (e) { return {}; }
    }
    if (!v || typeof v !== 'object' || Array.isArray(v)) { return {}; }
    return v;
  };

  // Firecrawl kaaraa tuloksen muotoon { success, data: { news, web } }.
  // Tuetaan myos suoraa { news, web } -rakennetta.
  const root = parse(inputs.scraped);
  const data = (root.data && typeof root.data === 'object' && !Array.isArray(root.data)) ? root.data : root;
  const news = Array.isArray(data.news) ? data.news : [];
  const web = Array.isArray(data.web) ? data.web : [];

  // Siivoa markdown: poista linkki- ja kuvasyntaksi seka navigaatiorivit,
  // jotta mukaan jaavat vain oikeat leipatekstikappaleet.
  const cleanBody = (raw) => {
    let t = String(raw || '');
    t = t.replace(/!\[[^\]]*\]\([^)]*\)/g, ' ');
    t = t.replace(/\[([^\]]*)\]\([^)]*\)/g, '$1');
    t = t.replace(/[`*_>#]+/g, ' ');
    const lines = t.split(/\r?\n/).map((x) => x.replace(/\s+/g, ' ').trim()).filter(Boolean);
    const keep = [];
    for (const line of lines) {
      const words = line.split(' ').length;
      const sentences = (line.match(/[.!?](\s|$)/g) || []).length;
      if (sentences === 0 && (words < 8 || line.length < 80)) { continue; }
      if (/^(skip to|sign in|log in|menu|search|close|share|read more|cookie|leave the|accept|subscribe|advertisement|most popular)/i.test(line)) { continue; }
      keep.push(line);
    }
    let out = keep.join(' ').replace(/\s{2,}/g, ' ').trim();
    const m = out.match(/[A-Za-z\u00c4\u00d6\u00c5\u00e4\u00f6\u00e5][^.!?]{60,}[.!?]/);
    if (m && m.index > 0 && m.index < 800) { out = out.slice(m.index); }
    return out;
  };

  const seen = {};
  const lines = [];
  const items = news.concat(web).filter((x) => x && (x.markdown || x.snippet || x.description));
  for (let i = 0; i < items.length && lines.length < 6; i++) {
    const it = items[i];
    const url = it.url || (it.metadata && it.metadata.sourceURL) || '';
    if (url && seen[url]) { continue; }
    if (url) { seen[url] = true; }
    const title = cut(it.title || '', 180);
    const src = domain(url);
    const date = cut(it.date || '', 40);
    let body = cleanBody(it.markdown || '');
    if (body.length < 200) {
      const md = it.metadata || {};
      body = cut(md.pageSummary || md.description || it.description || it.snippet || '', 2000);
    } else {
      body = cut(body, 2000);
    }
    const meta = [date, src].filter(Boolean).join(', ');
    lines.push('- ' + (title || '(ei otsikkoa)') + (meta ? ' [' + meta + ']' : '') + (url ? ' (' + url + ')' : '') + (body ? ' : ' + body : ''));
  }

  let out = lines.length ? lines.join(SEP) : 'ei artikkeleita';
  if (out.length > 16000) { out = out.slice(0, 16000) + ' ... (lyhennetty)'; }

  return {
    scrapedNews: 'VIIKON ARTIKKELIEN KOKOTEKSTIT: ' + out,
    scrapedCount: lines.length
  };
};

// step_13 (Lauantai): tiivistys LLM:lle. Kopio jaetusta step9.js:sta sillä erotuksella,
// että uutisrivit sisältävät lahteen URL:n, jotta raportti voidaan lahteistaa.
export const code = async (inputs) => {
  const SEP = '  ;;  ';

  const parseResults = (value) => {
    let v = value;
    if (typeof v === 'string') {
      const t = v.trim();
      if (!t) { return []; }
      try { v = JSON.parse(t); } catch (e) { return [{ title: '', content: t }]; }
    }
    if (Array.isArray(v)) { return v; }
    if (v && Array.isArray(v.results)) { return v.results; }
    if (v && typeof v === 'object') { return [v]; }
    return [];
  };

  const collapse = (text) => String(text || '')
    .replace(/\s+/g, ' ')
    .replace(/([A-Za-z\u00c4\u00d6\u00c5]{4,}?)\1{2,}/g, '$1')
    .replace(/\b([A-Za-z\u00c4\u00d6\u00c5]{3,})(?:\s+\1\b){2,}/gi, '$1')
    .replace(/"/g, "'")
    .replace(/\\/g, '/')
    .trim();

  const flatten = (text) => String(text === null || text === undefined ? '' : text)
    .replace(/[\r\n\t]+/g, SEP)
    .replace(/[ ]{2,}/g, ' ')
    .split(SEP).map((part) => part.trim()).filter(Boolean).join(SEP);

  const cut = (text, limit) => {
    const t = collapse(text);
    if (t.length <= limit) { return t; }
    const slice = t.slice(0, limit);
    const space = slice.lastIndexOf(' ');
    return (space > limit * 0.6 ? slice.slice(0, space) : slice) + ' ...';
  };

  const domain = (url) => {
    const m = String(url || '').match(/^https?:\/\/([^\/]+)/i);
    return m ? m[1].replace(/^www\./i, '') : '';
  };

  const publishedTime = (raw) => {
    const value = String(raw === null || raw === undefined ? '' : raw).trim();
    if (!value) { return null; }
    const direct = Date.parse(value);
    if (!isNaN(direct)) { return direct; }
    const rel = value.toLowerCase().match(/(\d+)\s*(minute|min|hour|h|day|d|week|wk)/);
    if (rel) {
      const amount = Number(rel[1]);
      const unit = rel[2];
      const hours = unit.startsWith('min') ? amount / 60
        : (unit === 'hour' || unit === 'h') ? amount
          : (unit === 'day' || unit === 'd') ? amount * 24
            : amount * 24 * 7;
      return Date.now() - hours * 3600000;
    }
    return null;
  };

  const ageLabel = (epoch, freshHours) => {
    if (epoch === null) { return ''; }
    const hours = (Date.now() - epoch) / 3600000;
    if (!isFinite(hours) || hours < 0) { return ''; }
    const tag = hours <= freshHours ? 'TUORE' : 'VANHEMPI';
    if (hours < 1) { return 'TUORE, alle 1 h sitten'; }
    if (hours < 48) { return tag + ', ' + Math.round(hours) + ' h sitten'; }
    return tag + ', ' + Math.round(hours / 24) + ' vrk sitten';
  };

  const freshHours = Number(inputs.fresh_hours);
  const freshLimit = isFinite(freshHours) && freshHours > 0 ? freshHours : 3;

  const compact = (label, resultsValue, answerValue, limit) => {
    const items = parseResults(resultsValue)
      .map((item) => {
        const i = item || {};
        return { item: i, at: publishedTime(i.published_date || i.publishedDate || i.published_at || i.date || '') };
      })
      .sort((a, b) => {
        if (a.at === null && b.at === null) { return 0; }
        if (a.at === null) { return 1; }
        if (b.at === null) { return -1; }
        return b.at - a.at;
      })
      .slice(0, 8);

    const lines = items.map((entry) => {
      const i = entry.item;
      const title = cut(i.title || i.name || '', 170);
      const text = cut(i.content || i.text || i.description || i.snippet || '', 700);
      const date = cut(i.published_date || i.publishedDate || i.published_at || i.date || '', 40);
      const age = ageLabel(entry.at, freshLimit);
      const url = String(i.url || i.link || '');
      const src = domain(url);
      const meta = [date, age, src].filter(Boolean).join(', ');
      return '- ' + (title || '(ei otsikkoa)') + (meta ? ' [' + meta + ']' : '') + (url ? ' (' + url + ')' : '') + (text ? ' : ' + text : '');
    });

    const answer = cut(answerValue || '', 1600);
    const head = label ? label + ' - ' : '';
    let out = head + 'tiivistelma: ' + (answer || 'ei tiivistelmaa') + SEP + head + 'artikkelit (uusin ensin): ' + (lines.length ? lines.join(SEP) : 'ei uutisia');
    if (out.length > limit) { out = out.slice(0, limit) + ' ... (lyhennetty)'; }
    return out;
  };

  // Tapahtumahakujen tulokset voivat tulla merkkijonona tai valmiina listana.
  // Muunnetaan ne luettavaksi tekstiksi, jotta LLM ei saa [object Object] -roskaa.
  const renderResults = (value) => {
    if (value === null || value === undefined || value === '') { return 'ei tuloksia'; }
    if (typeof value === 'string') {
      const t = value.trim();
      if (!t) { return 'ei tuloksia'; }
      if (t.charAt(0) === '[' || t.charAt(0) === '{') {
        try { return renderResults(JSON.parse(t)); } catch (e) { return flatten(t); }
      }
      return flatten(t);
    }
    if (Array.isArray(value)) {
      if (!value.length) { return 'ei tuloksia'; }
      return value.map((entry) => {
        const i = entry || {};
        const title = cut(i.title || i.name || '', 160);
        const url = String(i.url || i.link || '');
        const text = cut(i.content || i.text || i.description || i.snippet || '', 400);
        const meta = [cut(i.published_date || i.publishedDate || i.published_at || i.date || '', 40), domain(url)].filter(Boolean).join(', ');
        return '- ' + (title || '(ei otsikkoa)') + (meta ? ' [' + meta + ']' : '') + (url ? ' (' + url + ')' : '') + (text ? ' : ' + text : '');
      }).join(SEP);
    }
    return flatten(String(value));
  };

  const watch = inputs.watchlist ? flatten(inputs.watchlist) : 'ei tunnistettuja odotettuja tapahtumia';

  return {
    newsAsia: compact(inputs.label_asia || '', inputs.step_7_results, inputs.step_7_answer, 7000),
    newsEurope: compact(inputs.label_europe || '', inputs.step_8_results, inputs.step_8_answer, 7000),
    watchlist: 'ODOTETUT TAPAHTUMAT JA NIIDEN TULOKSET - seurantalista: ' + watch
      + SEP + 'TAPAHTUMA 1 - hautulos: ' + (cut(inputs.step_15_answer, 1600) || 'ei tiivistelmaa') + SEP + renderResults(inputs.step_15_results)
      + SEP + 'TAPAHTUMA 2 - hautulos: ' + (cut(inputs.step_16_answer, 1600) || 'ei tiivistelmaa') + SEP + renderResults(inputs.step_16_results)
      + SEP + 'TAPAHTUMA 3 - hautulos: ' + (cut(inputs.step_17_answer, 1600) || 'ei tiivistelmaa') + SEP + renderResults(inputs.step_17_results)
      + SEP + 'HUOM: tarkista jokaisen tapahtuman tila artikkelien julkaisuajoista ja vertaa nykyhetkeen. Ennakkouutisen sanamuoto ei kerro, onko tapahtuma jo toteutunut.',
    marketData: flatten(inputs.market_data),
    eventQuotes: inputs.step_18_quotes ? flatten(inputs.step_18_quotes) : ''
  };
};

